SELECT (DATE_TRUNC('DAY', "USAGE_DAY")) AS "TIME_BUCKET", (CAST(CASE WHEN (SUM(CREDITS_COMPUTE)) = 0 OR (SUM(CREDITS_COMPUTE)) IS NULL THEN NULL ELSE CAST((SUM(CREDITS_CLOUD_SERVICES_RAW)) AS DECIMAL(38, 15)) / CAST((SUM(CREDITS_COMPUTE)) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS "COST_CLOUD_SERVICES_RATIO" FROM (SELECT "SERVICE_TYPE" AS SERVICE_TYPE, CAST("USAGE_DATE" AS DATE) AS USAGE_DAY, (CAST("CREDITS_USED_COMPUTE" AS DECIMAL(38, 9))) AS CREDITS_COMPUTE, (CAST("CREDITS_USED_CLOUD_SERVICES" AS DECIMAL(38, 9))) AS CREDITS_CLOUD_SERVICES_RAW, (CAST("CREDITS_ADJUSTMENT_CLOUD_SERVICES" AS DECIMAL(38, 9))) AS CREDITS_CLOUD_SERVICES_ADJUSTMENT, (CAST("CREDITS_USED_CLOUD_SERVICES" + "CREDITS_ADJUSTMENT_CLOUD_SERVICES" AS DECIMAL(38, 9))) AS CREDITS_CLOUD_SERVICES_BILLED, (CAST("CREDITS_USED" AS DECIMAL(38, 9))) AS CREDITS_USED, (CAST("CREDITS_BILLED" AS DECIMAL(38, 9))) AS CREDITS_BILLED, ("_ACCOUNT") AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). */ FROM metering_daily_history) AS base GROUP BY (DATE_TRUNC('DAY', "USAGE_DAY")) ORDER BY "COST_CLOUD_SERVICES_RATIO" DESC, "TIME_BUCKET" LIMIT 100
